#!/usr/bin/env bash\nset -e\n\n# Mock rationale: deterministic comment selection based on base image \"alpine\"\nexpected=$(cat <<'EOF'\n# Fuel the container with hope\nFROM alpine\nRUN apk add --no-cache python3 && echo 'print(\"Hello from the apocalypse!\")' > /app.py && CMD [\"python3\",\"/app.py\"]\nEOF\n)\n\noutput=$(../src/generator.sh alpine python)\n\nif [[ \"$output\" != \"$expected\" ]]; then\n  echo \"Test failed\"\n  echo \"Expected:\"\n  echo \"$expected\"\n  echo \"Got:\"\n  echo \"$output\"\n  exit 1\nfi\n\necho \"Test passed\"\n
